; JVC infrared frame with a 38 kHz carrier; one code per host word (address | command << 8), acknowledged
; Generated by escgen from protocols/jvc_tx.yaml: edit the table and
; regenerate (python -m escgen), or take this file over by hand.
; Reference: SB-Projects, JVC Protocol, www.sbprojects.net/knowledge/ir/jvc.php: 38 kHz carrier, 526 us bursts (20 carrier periods), 0 = 1.05 ms and 1 = 2.10 ms bit times, 8.4 ms AGC burst and 4.2 ms space, 8-bit address then 8-bit command LSB first, repeated every 50 to 60 ms
; Every edge is a DRIVE event at an absolute deadline; escert certifies it.

.default CTX, 0
.default CLK_KHZ, 25000                ; core clock in kHz
.equ PERIOD, (CLK_KHZ * 10 + 190) // 380
.equ T, 20 * PERIOD
.equ GAP, CLK_KHZ * 10
.equ C_PERIOD, PERIOD
.equ C_HIGH, (PERIOD + 1) // 3
.default PIN_IR, 0
.equ P_IR, 1 << PIN_IR

.own  PIN_IR, CTX
.entry CTX, main

main:
    ADDT  16                          ; first deadline after the first commit
    EMIT  P_IR, 0, P_IR               ; idle levels
    ADDT  1
packet:
    POP   r1                          ; one word per packet (waits for the host)
    WAITT                             ; the last packet's final phase has ended
    RDTIME r3
    ADDI  r3, 64
    SETT  r3
    LDLC  (16 * T) // C_PERIOD        ; agc: carrier pulses
    CALL  burst
    ADDT  8 * T - 64                  ; no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
    MOVI  r3, 16                      ; 16 bits, LSB first, each zero or one
bit1:
    SHR   r1, 1                       ; C = the next bit
    JC    one2
    LDLC  (T) // C_PERIOD             ; zero: carrier pulses
    CALL  burst
    ADDT  T                           ; no change, no event
    JMP   next3
one2:
    LDLC  (T) // C_PERIOD             ; one: carrier pulses
    CALL  burst
    ADDT  3 * T - 64                  ; no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
next3:
    MOVI  r0, 1
    SUB   r3, r0                      ; Z after the last bit
    JNZ   bit1
    LDLC  (T) // C_PERIOD             ; stop: carrier pulses
    CALL  burst
    ADDT  GAP - 64                    ; gap: no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
    MOVI  r3, 1
    PUSH  r3                          ; packet sent
    JMP   packet

; ---- burst: lc carrier pulses from tmr; returns with tmr = start + lc * C_PERIOD
burst:
    EMIT  P_IR, P_IR, P_IR
    ADDT  C_HIGH
    EMIT  P_IR, 0, P_IR
    ADDT  C_PERIOD - C_HIGH
    DJNZ  burst
    RET
